package com.digitalhealth.service; import com.digitalhealth.dto.NotificationDTO; import com.digitalhealth.model.*; import com.digitalhealth.repository.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class NotificationService {private final NotificationRepository repo;public NotificationService(NotificationRepository r){repo=r;} public void create(Worker w,String message,String type){Notification n=new Notification();n.setWorker(w);n.setMessage(message);n.setType(type);repo.save(n);} public List<NotificationDTO> list(Long workerId){return repo.findByWorkerIdOrderByCreatedAtDesc(workerId).stream().map(this::dto).toList();}public NotificationDTO read(Long workerId,Long id){Notification n=repo.findById(id).filter(x->x.getWorker().getId().equals(workerId)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found"));n.setReadStatus(true);return dto(repo.save(n));}private NotificationDTO dto(Notification n){var d=new NotificationDTO();d.id=n.getId();d.message=n.getMessage();d.type=n.getType();d.read=n.isReadStatus();d.createdAt=n.getCreatedAt();return d;}}
